sections.usage_vi:
```
Sử dụng framework Agent Skills để tạo một skill tái sử dụng cho [TASK_NAME] bao gồm: 1) mục tiêu rõ ràng, 2) cấu trúc input/output, 3) logic thực thi từng bước, và 4) xử lý lỗi. Định dạng skill dưới dạng một đối tượng JSON với các trường: 'name', 'description', 'input_schema', 'output_schema', 'execution_steps', và 'error_handling'. Ví dụ về tác vụ: 'tóm tắt ticket hỗ trợ khách hàng'.
```
Copy

```
```json
{
  "name": "ticket_summarizer_v1",
  "description": "Tự động tạo bản tóm tắt ngắn gọn các ticket hỗ trợ khách hàng để phân loại và phản hồi nhanh hơn.",
  "input_schema": {
    "type": "object",
    "properties": {
      "ticket_id": {"type": "string", "description": "Mã định danh duy nhất cho ticket hỗ trợ"},
      "customer_query": {"type": "string", "description": "Toàn bộ văn bản yêu cầu/sự cố của khách hàng"},
      "ticket_metadata": {
        "type": "object",
        "properties": {
          "priority": {"type": "string", "enum": ["low", "medium", "high", "critical"]},
          "category": {"type": "string", "description": "Danh mục sự cố (ví dụ: thanh toán, kỹ thuật, truy cập tài khoản)"},
          "created_at": {"type": "string", "format": "date-time"}
        }
      }
    },
    "required": ["ticket_id", "customer_query"]
  },
  "output_schema": {
    "type": "object",
    "properties": {
      "summary": {
        "type": "string",
        "description": "Tóm tắt ngắn gọn về ticket (tối đa 150 ký tự)"
      },
      "key_issues": {
        "type": "array",
        "items": {"type": "string"},
        "description": "Danh sách 2-3 sự cố chính được xác định"
      },
      "recommended_action": {
        "type": "string",
        "enum": ["assign_to_team", "escalate", "auto_reply", "pending_customer_info"]
      },
      "confidence_score": {
        "type": "number",
        "minimum": 0,
        "maximum": 1,
        "description": "Độ tin cậy của AI đối với bản tóm tắt và phân loại"
      }
    },
    "required": ["summary", "key_issues", "recommended_action", "confidence_score"]
  },
  "execution_steps": [
    {
      "step": 1,
      "action": "Trích xuất và chuẩn hóa các thực thể chính từ customer_query bằng các kỹ thuật NLP.",
      "details": {
        "entities": ["product_name", "issue_type", "urgency_indicators"],
        "method": "spaCy với mô hình nhận dạng thực thể tùy chỉnh"
      }
    },
    {
      "step": 2,
      "action": "Phân loại ticket vào các danh mục được xác định trước bằng mô hình BERT đã được fine-tune.",
      "details": {
        "categories": ["billing", "technical", "account_access", "feature_request", "complaint"],
        "threshold": 0.85
      }
    },
    {
      "step": 3,
      "action": "Tạo bản tóm tắt và các sự cố chính bằng mô hình tóm tắt (ví dụ: PEGASUS).",
      "details": {
        "max_length": 150,
        "include_metadata": true
      }
    },
    {
      "step": 4,
      "action": "Xác định hành động được đề xuất dựa trên danh mục, độ ưu tiên và các thực thể được trích xuất.",
      "details": {
        "rules": [
          "Nếu category = 'billing' và priority = 'high', đề xuất 'escalate'",
          "Nếu category = 'technical' và có urgency_indicators, đề xuất 'assign_to_team'",
          "Nếu customer_query chứa 'refund', đề xuất 'escalate' bất kể danh mục nào"
        ]
      }
    },
    {
      "step": 5,
      "action": "Tính toán điểm tin cậy dựa trên xác suất của mô hình và kết quả trích xuất thực thể thành công.",
      "details": {
        "formula": "(entity_extraction_score + classification_score + summarization_score) / 3"
      }
    }
  ],
  "error_handling": {
    "missing_data": {
      "action": "Sử dụng các giá trị mặc định cho các trường metadata bị thiếu (ví dụ: priority = 'medium').",
      "fallback": "Nếu customer_query trống, trả về lỗi chỉ kèm theo ticket_id."
    },
    "low_confidence": {
      "threshold": 0.6,
      "action": "Đánh dấu để con người xem xét lại cùng với điểm tin cậy trong đầu ra.",
      "suggestion": "Thêm 'pending_human_review' vào recommended_action"
    },
    "model_failure": {
      "action": "Trả về dữ liệu ticket thô cùng thông báo lỗi nếu quá trình tóm tắt/phân loại thất bại.",
      "retry": "Thử lại một lần với mô hình dự phòng (ví dụ: DistilBERT thay vì BERT)"
    }
  }
}
```
